create table if not exists classroom_audit (id uuid primary key default gen_random_uuid(), actor_user_id uuid, room_id uuid, action text not null, target_type text, target_id uuid, metadata_json jsonb default '{}'::jsonb, created_at timestamptz default now()); alter table classroom_audit enable row level security; create index if not exists idx_classroom_audit_room on classroom_audit(room_id); create index if not exists idx_classroom_audit_created on classroom_audit(created_at);
